// Calcula los nombres de carpeta, resuelve el ID del folder del mes a
// partir de un mapa hardcoded (las 12 carpetas 2026-MM Mes ya existen),
// y arma el contenido del README.txt.

const MESES = {
  '01': 'Enero', '02': 'Febrero', '03': 'Marzo', '04': 'Abril',
  '05': 'Mayo', '06': 'Junio', '07': 'Julio', '08': 'Agosto',
  '09': 'Septiembre', '10': 'Octubre', '11': 'Noviembre', '12': 'Diciembre'
};

// IDs de las carpetas 2026-MM dentro de "Evidencias Mantenimientos / 2026".
// Si creás los años 2027+ hay que agregar sus mapas acá.
const MESES_FOLDER_IDS = {
  '2026': {
    '01': '1oMDtMWDJRr-T9YWx4jrxRDiRpGiA36SK',
    '02': '1FSB2_YUMuNmWkDzZ59mbEqwTT7T_yaPS',
    '03': '1LLkh3n4XriO-FvUwCbqnuTrIVIGrFfLz',
    '04': '1XUWEpPqFccwMv23m7N-wAEo3cVwyuo9N',
    '05': '13iOn-hKulQprABxAm3_kesDSVLKdOoa9',
    '06': '1jP-2zOOEltzqozn949A5JoSk6eKOdbqz',
    '07': '1ZpD8KWwpldHQ1USJ7nfu_lUrYRvLELAB',
    '08': '172iouxbOST_GvrU7LplmXw06o9QjLQr3',
    '09': '1_G2Tj-9MqLGO_LXDDyALKkLxZeuRq5ZT',
    '10': '1PeNA-4ALKlJffMA7RNUvSq230-VxLcO0',
    '11': '1X47l_STYpMtYsj_hi93UEwHPVU8jDvL6',
    '12': '1ID_X7mSWBxmQfnDHzw63oz61EkzVogne'
  }
};

const body = $input.first().json.body || $input.first().json;

const fecha = body.fecha_ejecucion; // 'YYYY-MM-DD'
if (!fecha || !/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
  throw new Error('fecha_ejecucion inválido o faltante (esperado YYYY-MM-DD): ' + fecha);
}

const anio = fecha.slice(0, 4);
const mes = fecha.slice(5, 7);
const nombreMes = MESES[mes] || mes;

const monthFolderId = (MESES_FOLDER_IDS[anio] || {})[mes];
if (!monthFolderId) {
  throw new Error('No hay carpeta de mes creada para ' + anio + '-' + mes + '. Crealas manualmente o actualizá el mapa MESES_FOLDER_IDS.');
}

const slug = (s) => (s || '').toString()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // sin tildes
  .replace(/[^a-zA-Z0-9]+/g, '') // sin espacios ni símbolos
  .trim();

const proveedorSlug = slug(body.proveedor);
const categoriaSlug = slug(body.categoria);
const sedes = (body.sedes || []).join('-');

const mesFolderName = `${anio}-${mes} ${nombreMes}`;
const jornadaFolderName = `${fecha}_${proveedorSlug}_${categoriaSlug}_${sedes}`;

// README
const mantenimientos = body.mantenimientos || [];
const filaMnt = mantenimientos.map((m, i) =>
  ` ${String(i + 1).padStart(2, ' ')} | ${(m.equipo_codigo || '').padEnd(10)} | ${(m.equipo_nombre || '').padEnd(40)} | ${(m.sede || '').padEnd(4)} | ${m.mnt_codigo}`
).join('\n');

const readme = `================================================================
JORNADA DE MANTENIMIENTO
================================================================

DATOS GENERALES
---------------
Fecha de ejecución : ${fecha}
Hora de inicio    : ${body.hora_inicio || '-'}
Hora de fin       : ${body.hora_fin || '-'}
Proveedor         : ${body.proveedor || '-'}
Técnico responsable: ${body.tecnico || '-'}
Categoría         : ${body.categoria || '-'}
Sedes atendidas   : ${(body.sedes || []).join(', ')}


EQUIPOS CUBIERTOS (${mantenimientos.length})
-------------------
 # | Equipo    | Nombre / Ubicación                     | Sede | Código MANTIX
---|-----------|------------------------------------------|------|---------------
${filaMnt}


DOCUMENTOS ADJUNTOS EN ESTA CARPETA
-----------------------------------
[ ] 00_INFORME_CONSOLIDADO.pdf   (informe único entregado por el proveedor)
[ ] 02_Evidencias_Fotograficas/  (fotos antes/después por equipo)
[ ] 03_Checklists_Firmados/      (checklist firmado por equipo)
[ ] 04_Actas_Firmas/             (acta de entrega y recibido)


OBSERVACIONES
-------------
${body.observaciones || '-'}


================================================================
Generado automáticamente por workflow n8n (Mantix - Evidencias Drive).
================================================================
`;

return [{ json: {
  anio,
  mes,
  nombreMes,
  mesFolderName,
  jornadaFolderName,
  monthFolderId,
  readme,
  payload: body
}}];

// Captura el id/url de la carpeta de jornada recién creada,
// y propaga el readme + jornadaFolderName para los próximos nodos.
const jornada = $input.first().json;
const prev = $('Prepare names + README').first().json;

return [{ json: {
  ...prev,
  jornadaFolderId: jornada.id,
  jornadaFolderUrl: `https://drive.google.com/drive/folders/${jornada.id}`
}}];

// Convierte el string del README a binary (campo 'data') para que el
// nodo 'Drive: Upload README' pueda subirlo como archivo.
const prev = $('Capture jornada ID').first().json;
const text = prev.readme || '';
const b64 = Buffer.from(text, 'utf-8').toString('base64');

return [{
  json: prev,
  binary: {
    data: {
      data: b64,
      mimeType: 'text/plain',
      fileName: 'README.txt'
    }
  }
}];
